import{_ as a,o as e,c as t,am as i}from"./chunks/framework.CiF4W93w.js";const g=JSON.parse('{"title":"Spring AI","description":"","frontmatter":{"title":"Spring AI","excerpt":"摘要","date":"2025-11-14 16:34:41","updated":"2025-11-14 16:34:41"},"headers":[],"relativePath":"框架/AI 框架/Spring AI/index.md","filePath":"框架/AI 框架/Spring AI/index.md","lastUpdated":null}'),n={name:"框架/AI 框架/Spring AI/index.md"};function l(p,r,o,s,h,c){return e(),t("div",null,[...r[0]||(r[0]=[i('<ul><li>官网： <a href="https://spring.io/projects/spring-ai" target="_blank" rel="noreferrer">https://spring.io/projects/spring-ai</a></li><li>spring ai 的中文教程： <a href="https://www.spring-doc.cn/spring-ai/1.1.0/index.html" target="_blank" rel="noreferrer">https://www.spring-doc.cn/spring-ai/1.1.0/index.html</a> ；</li><li>学习使用版本： 1.1.0</li></ul><hr><p>总体来说，现在大模型的使用还在探索阶段，甚至有些LLM框架提出的概念是：使用越少的工具，让大模型本身去工作（因为有可能随着大模型的发展，有些工具的使用反而是限制了它的发挥）。</p><p>因此还是看实际的使用效果和具体的提效去看大模型框架和大模型本身的发展。</p><h3 id="聊天对话" tabindex="-1">聊天对话 <a class="header-anchor" href="#聊天对话" aria-label="Permalink to &quot;聊天对话&quot;">​</a></h3><ul><li>聊天对话： <a href="https://www.spring-doc.cn/spring-ai/1.1.0/api_chatmodel.html" target="_blank" rel="noreferrer">https://www.spring-doc.cn/spring-ai/1.1.0/api_chatmodel.html</a></li><li>聊天记忆： <a href="https://www.spring-doc.cn/spring-ai/1.1.0/api_chat-memory.html" target="_blank" rel="noreferrer">https://www.spring-doc.cn/spring-ai/1.1.0/api_chat-memory.html</a></li></ul><h3 id="工具-函数调用" tabindex="-1">工具 函数调用 <a class="header-anchor" href="#工具-函数调用" aria-label="Permalink to &quot;工具 函数调用&quot;">​</a></h3><blockquote><p>工具 函数调用 和 MCP 的区别？</p></blockquote><p>工具调用是“目的”，而 MCP 是实现这一目的的“手段”之一</p><blockquote><p><strong>“工具”具体指什么？</strong></p></blockquote><p>工具确实是指<strong>本地的方法、脚本或函数</strong>，让大模型在需要时调用.</p><h3 id="rag" tabindex="-1">RAG <a class="header-anchor" href="#rag" aria-label="Permalink to &quot;RAG&quot;">​</a></h3><ul><li>知识检索的一种工具。</li><li>RAG： <a href="https://www.spring-doc.cn/spring-ai/1.1.0/api_retrieval-augmented-generation.html" target="_blank" rel="noreferrer">https://www.spring-doc.cn/spring-ai/1.1.0/api_retrieval-augmented-generation.html</a></li></ul><h3 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h3><p><strong>模型上下文协议 (Model Context Protocol, MCP)</strong> 是一种标准化协议，旨在以结构化的方式使人工智能模型能够与外部工具和资源进行交互。</p><ul><li>MCP： <a href="https://www.spring-doc.cn/spring-ai/1.1.0/api_mcp_mcp-overview.html" target="_blank" rel="noreferrer">https://www.spring-doc.cn/spring-ai/1.1.0/api_mcp_mcp-overview.html</a></li><li><a href="/java/框架/AI 框架/Spring AI/MCP Java SDK：标准与架构全面分析.html">MCP Java SDK的实现分析</a></li><li></li></ul><hr><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><p>别人分享的一些文章，有兴趣且有空的时候可以看一下：新MCP注解开发MCP Server <a href="https://articles.zsxq.com/id_8wqg7j81poq6.html" target="_blank" rel="noreferrer">https://articles.zsxq.com/id_8wqg7j81poq6.html</a></p>',19)])])}const m=a(n,[["render",l]]);export{g as __pageData,m as default};
